import{_ as l,o as s,c as e,a0 as t}from"./chunks/framework.DqMqoJl9.js";const n="/assets/1_3.FRJH06Qt.png",o="/assets/1_2.DF45D2tJ.png",y=JSON.parse('{"title":"linux","description":"","frontmatter":{},"headers":[],"relativePath":"linux/base.md","filePath":"linux/base.md","lastUpdated":1791039142000}'),i={name:"linux/base.md"};function r(p,a,c,d,h,u){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="linux" tabindex="-1">linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;linux&quot;">​</a></h1><h2 id="vmware" tabindex="-1">vmware <a class="header-anchor" href="#vmware" aria-label="Permalink to &quot;vmware&quot;">​</a></h2><p>卸载VMware往往卸不干净，使用Vmware-install.client可以完全卸载</p><p>不建议在创建虚拟机的自动安装linux系统</p><h3 id="网络连接" tabindex="-1">网络连接 <a class="header-anchor" href="#网络连接" aria-label="Permalink to &quot;网络连接&quot;">​</a></h3><ul><li>桥接：和真实机一样的IP，使用真实网络连接，可以连接网络设备，推荐</li><li>NAT ：使用WM-8虚拟网卡，虚拟连接，可以上网，不可使用网络设备</li><li>Host-only：使用VM-1虚拟网卡，不能上网，只和本机连接</li></ul><p><img src="'+n+`" alt=""></p><h3 id="快照" tabindex="-1">快照 <a class="header-anchor" href="#快照" aria-label="Permalink to &quot;快照&quot;">​</a></h3><p>相当于备份，可以保存系统某个状态，建议装好系统就保存一次快照</p><h2 id="磁盘分区" tabindex="-1">磁盘分区 <a class="header-anchor" href="#磁盘分区" aria-label="Permalink to &quot;磁盘分区&quot;">​</a></h2><h3 id="磁盘分区-1" tabindex="-1">磁盘分区 <a class="header-anchor" href="#磁盘分区-1" aria-label="Permalink to &quot;磁盘分区&quot;">​</a></h3><p>磁盘分区是使用分区编辑器在磁盘上划分几个逻辑部分。碟片一旦划分成数个分区，不同类的目录与文件可以存储进不同的分区</p><h3 id="分区类型" tabindex="-1">分区类型 <a class="header-anchor" href="#分区类型" aria-label="Permalink to &quot;分区类型&quot;">​</a></h3><ul><li>主分区：最多只能4个</li><li>扩展分区：最多只能有1个，主分区加扩展分区最多有4个，不能写入数据，只能包含逻辑分区</li><li>逻辑分区：</li></ul><h3 id="格式化" tabindex="-1">格式化 <a class="header-anchor" href="#格式化" aria-label="Permalink to &quot;格式化&quot;">​</a></h3><p>格式化是写入文件系统，不单是清空磁盘</p><p>格式化（高级格式化）有称逻辑格式化，它是指根据用户选定的文件系统（如FAT16, FAT32, NTFS, EXT2, EXT3, EXT4等），在磁盘的特 定区域写入特定数据，在分区中划出一片用于存放文件分配表、目录表等用户文件管理的磁盘空间</p><h2 id="硬件设备文件名" tabindex="-1">硬件设备文件名 <a class="header-anchor" href="#硬件设备文件名" aria-label="Permalink to &quot;硬件设备文件名&quot;">​</a></h2><h3 id="linux下所有设备皆文件" tabindex="-1">linux下所有设备皆文件 <a class="header-anchor" href="#linux下所有设备皆文件" aria-label="Permalink to &quot;linux下所有设备皆文件&quot;">​</a></h3><p>每一个设备都有一个设备文件名</p><table tabindex="0"><thead><tr><th style="text-align:left;">硬件</th><th style="text-align:left;">设备文件名</th></tr></thead><tbody><tr><td style="text-align:left;">IDE硬盘</td><td style="text-align:left;">/dev/hd[a-d]</td></tr><tr><td style="text-align:left;">SCSI/SATA/USB硬盘</td><td style="text-align:left;">/dev/sd[a-p]</td></tr><tr><td style="text-align:left;">光驱</td><td style="text-align:left;">/dev/cdrom或/dev/hdc</td></tr><tr><td style="text-align:left;">软盘</td><td style="text-align:left;">/dev/fd[0-1]</td></tr><tr><td style="text-align:left;">打印机（25针）</td><td style="text-align:left;">/dev/lp[0-2]</td></tr><tr><td style="text-align:left;">打印机（USB）</td><td style="text-align:left;">/dev/usb/lp[0-15]</td></tr><tr><td style="text-align:left;">鼠标</td><td style="text-align:left;">/dev/mouse</td></tr></tbody></table><h3 id="分区设备文件名" tabindex="-1">分区设备文件名 <a class="header-anchor" href="#分区设备文件名" aria-label="Permalink to &quot;分区设备文件名&quot;">​</a></h3><h4 id="设备文件名" tabindex="-1">设备文件名 <a class="header-anchor" href="#设备文件名" aria-label="Permalink to &quot;设备文件名&quot;">​</a></h4><ul><li>/dev/hda1（IDE硬盘接口）</li><li>/dev/sda1（SCSI硬盘接口、SATA硬盘接口） （sd表示硬盘，a表示第一个硬盘，1表示第一个分区）</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>注意：逻辑分区是从5开始，因为1-4表示主分区</p></div><ul><li>光驱用的就IDE接口，比较老，传输数率为每秒1百多兆</li><li>SCSI是老式服务器硬盘的传输接口，每秒2百兆</li><li>SATA为目前硬盘的标准接口分为SATA1、SATA2、SATA3代，SATA3可达每秒5百兆</li></ul><h4 id="必须分区-以下两个分区是必须要分的" tabindex="-1">必须分区（以下两个分区是必须要分的） <a class="header-anchor" href="#必须分区-以下两个分区是必须要分的" aria-label="Permalink to &quot;必须分区（以下两个分区是必须要分的）&quot;">​</a></h4><ul><li>/（根分区）</li><li>swap分区，即虚拟内存（交换分区，内存2倍，不超过2GB）</li></ul><h4 id="推荐分区" tabindex="-1">推荐分区 <a class="header-anchor" href="#推荐分区" aria-label="Permalink to &quot;推荐分区&quot;">​</a></h4><ul><li>/boot（启动分区，200MB）</li></ul><h3 id="挂载" tabindex="-1">挂载 <a class="header-anchor" href="#挂载" aria-label="Permalink to &quot;挂载&quot;">​</a></h3><p>给分区分配盘符的过程叫挂载</p><ul><li>windows下的盘符（如本地磁盘E），就相当于是挂载点，linux下没有盘符这个概念，叫挂载点</li><li>linux中不是拿abcd作为盘符，而是用目录作为盘符，任何一个目录都可以作为一个分区（即盘符）</li></ul><h2 id="命令提示符" tabindex="-1">命令提示符 <a class="header-anchor" href="#命令提示符" aria-label="Permalink to &quot;命令提示符&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">[root@localhost </span><span style="color:#D73A49;">~</span><span style="color:#24292E;">]#</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>root</code> 当前登录用户</li><li><code>localhost</code> 主机名</li><li><code>~</code> 当前所在目录（~为home目录）</li><li><code>#</code> 超级用户的提示符</li><li><code>$</code> 普通用户的提示符</li></ul><h3 id="修改命令提示符" tabindex="-1">修改命令提示符 <a class="header-anchor" href="#修改命令提示符" aria-label="Permalink to &quot;修改命令提示符&quot;">​</a></h3><p>配置文件</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">profile        </span><span style="color:#6A737D;">// 每个用户登录时都会运行的环境变量设置</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要修改命令行提示符，需通过修改环境变量PS1来达到目的</p><p>命令列表的参数:</p><ul><li>\\u 显示当前用户的用户名（user name）</li><li>\\h 显示主机名（host name）</li><li>\\W 显示当前工作目录的名字（work directory）</li><li>\\w 当前所在的完整路径</li><li>$ 显示$符作为提示符，如果用户是root的话，则显示#号</li><li>\\d 现在的系统日期</li><li>\\t 现在的系统时间</li></ul><p>修改配置文件:</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">export</span><span style="color:#005CC5;"> PS1</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&#39;[</span><span style="color:#005CC5;">\\u</span><span style="color:#032F62;">@</span><span style="color:#005CC5;">\\h</span><span style="color:#032F62;">] </span><span style="color:#005CC5;">\\W\\$</span><span style="color:#032F62;"> &#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="文件基本属性" tabindex="-1">文件基本属性 <a class="header-anchor" href="#文件基本属性" aria-label="Permalink to &quot;文件基本属性&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">[root@www </span><span style="color:#D73A49;">/</span><span style="color:#24292E;">]# ls </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">l</span></span>
<span class="line"><span style="color:#24292E;">total </span><span style="color:#005CC5;">64</span></span>
<span class="line"><span style="color:#24292E;">dr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">xr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">xr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">x   </span><span style="color:#005CC5;">2</span><span style="color:#24292E;"> root root </span><span style="color:#005CC5;">4096</span><span style="color:#24292E;"> Dec </span><span style="color:#005CC5;">14</span><span style="color:#005CC5;">  2012</span><span style="color:#24292E;"> bin</span></span>
<span class="line"><span style="color:#24292E;">dr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">xr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">xr</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">x   </span><span style="color:#005CC5;">4</span><span style="color:#24292E;"> root root </span><span style="color:#005CC5;">4096</span><span style="color:#24292E;"> Apr </span><span style="color:#005CC5;">19</span><span style="color:#005CC5;">  2012</span><span style="color:#24292E;"> boot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><img src="`+o+'" alt=""></p><p>在Linux中第一个字符代表这个文件是目录、文件或链接文件等等</p><ul><li>[ d ] 目录</li><li>[ - ] 文件</li><li>[ l ] 链接文档(link file)</li><li>[ b ] 装置文件里面的可供储存的接口设备(可随机存取装置)</li><li>[ c ] 装置文件里面的串行端口设备，例如键盘、鼠标(一次性读取装置)</li></ul>',49)])])}const x=l(i,[["render",r]]);export{y as __pageData,x as default};
